"use client";

import React, { useState } from "react";
import { motion } from "framer-motion";
import { Check, ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";

interface WizardStepperOrbitProps {
  className?: string;
}

const STEPS = [
  { id: "account", label: "Account", hint: "Identity & contact" },
  { id: "workspace", label: "Workspace", hint: "Org & seats" },
  { id: "billing", label: "Billing", hint: "Plan & method" },
  { id: "review", label: "Review", hint: "Confirm & finish" },
];

export function WizardStepperOrbit({ className }: WizardStepperOrbitProps) {
  const [step, setStep] = useState(1);
  const total = STEPS.length;
  const pct = (step / (total - 1)) * 100;

  return (
    <div className={cn("flex flex-col gap-4 p-6 border border-white/5 bg-zinc-950/40 rounded-2xl shadow-2xl w-full", className)}>
      <div className="flex flex-col gap-1 font-mono select-none">
        <span className="text-[9px] uppercase tracking-widest font-bold text-primary">WIZARD_STEPPER_ORBIT</span>
        <span className="text-[8px] text-white/40 uppercase font-semibold">Connector progress · active orbit ring · keyboard friendly</span>
      </div>

      <div role="list" aria-label="Onboarding steps" className="relative grid grid-cols-4 gap-2 px-2">
        <div aria-hidden="true" className="absolute left-[12.5%] right-[12.5%] top-4 h-px bg-white/15">
          <motion.div
            className="h-full bg-primary"
            initial={false}
            animate={{ width: `${pct}%` }}
            transition={{ type: "spring", stiffness: 220, damping: 28 }}
          />
        </div>

        {STEPS.map((s, i) => {
          const state = i < step ? "done" : i === step ? "active" : "pending";
          return (
            <button
              key={s.id}
              type="button"
              onClick={() => setStep(i)}
              className="relative z-10 flex flex-col items-center gap-1.5 text-center"
              aria-current={state === "active" ? "step" : undefined}
            >
              <span className={cn(
                "relative flex h-8 w-8 items-center justify-center rounded-full border text-[11px] font-mono font-bold transition-colors",
                state === "done" && "border-primary bg-primary text-black",
                state === "active" && "border-primary bg-zinc-950 text-primary",
                state === "pending" && "border-white/15 bg-zinc-950 text-white/40",
              )}>
                {state === "active" && (
                  <motion.span
                    aria-hidden="true"
                    className="absolute inset-0 rounded-full border border-primary/40"
                    animate={{ scale: [1, 1.35, 1], opacity: [0.6, 0, 0.6] }}
                    transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
                  />
                )}
                {state === "done" ? <Check className="h-3.5 w-3.5" /> : i + 1}
              </span>
              <span className={cn("text-[11px] font-semibold", state === "pending" ? "text-white/40" : "text-white")}>{s.label}</span>
              <span className="text-[9px] font-mono uppercase tracking-widest text-white/40">{s.hint}</span>
            </button>
          );
        })}
      </div>

      <div className="flex items-center justify-between border-t border-white/10 pt-3">
        <button
          onClick={() => setStep((s) => Math.max(s - 1, 0))}
          disabled={step === 0}
          className="inline-flex items-center gap-1 rounded-md border border-white/10 px-2.5 py-1.5 text-xs font-semibold text-white/70 hover:bg-white/5 disabled:cursor-not-allowed disabled:opacity-40"
        >
          <ChevronLeft className="h-3.5 w-3.5" /> Back
        </button>
        <span className="text-[10px] font-mono uppercase tracking-widest text-white/40">
          step <span className="text-primary">{step + 1}</span> / {total}
        </span>
        <button
          onClick={() => setStep((s) => Math.min(s + 1, total - 1))}
          disabled={step === total - 1}
          className="inline-flex items-center gap-1 rounded-md bg-primary px-2.5 py-1.5 text-xs font-bold text-black hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-40"
        >
          Next <ChevronRight className="h-3.5 w-3.5" />
        </button>
      </div>
    </div>
  );
}
